Here's a robust implementation using Python's built-in `html.parser` module (no dependencies):

```python
from html.parser import HTMLParser


class _DataTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = None          # list of rows; None until the target table starts
        self.table_depth = 0      # how many <table> tags are open inside the target
        self.done = False         # set once the target table has been closed
        self.current_row = None   # list for the <tr> we're inside
        self.current_cell = None  # buffer (list of str chunks) for the <td> we're inside

    @staticmethod
    def _has_data_table_class(attrs):
        return any(name == 'class' and value == 'data-table' for name, value in attrs)

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if tag == 'table':
            if self.rows is None and self._has_data_table_class(attrs):
                self.rows = []
                self.table_depth = 1
            elif self.rows is not None:
                self.table_depth += 1
            return
        if self.rows is None:
            return
        if tag == 'tr' and self.table_depth == 1:
            if self.current_cell is not None:   # unterminated <td>
                self._end_cell()
            if self.current_row is not None:   # unterminated <tr>
                self._end_row()
            self.current_row = []
        elif tag == 'td' and self.table_depth == 1 and self.current_row is not None:
            if self.current_cell is not None:   # unterminated <td>
                self._end_cell()
            self.current_cell = []

    def handle_endtag(self, tag):
        if self.done or self.rows is None:
            return
        if tag == 'table':
            self.table_depth -= 1
            if self.table_depth == 0:
                self._flush()
        elif tag == 'tr' and self.table_depth == 1 and self.current_row is not None:
            if self.current_cell is not None:
                self._end_cell()
            self._end_row()
        elif tag == 'td' and self.current_cell is not None:
            self._end_cell()

    def handle_data(self, data):
        if self.current_cell is not None:
            self.current_cell.append(data)

    def _end_cell(self):
        if self.current_row is not None:
            self.current_row.append(''.join(self.current_cell))
        self.current_cell = None

    def _end_row(self):
        self.rows.append(self.current_row)
        self.current_row = None

    def _flush(self):
        if self.current_cell is not None:
            self._end_cell()
        if self.current_row is not None:
            self._end_row()
        self.done = True

    def close(self):
        super().close()
        if not self.done and self.rows is not None:
            self._flush()   # handle an unterminated table


def extract_data_table_rows(html):
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()
    return parser.rows or []
```

How it behaves:

- **Finds the first matching table**: it tracks `<table>` nesting depth, so a `data-table` nested inside another table is found correctly, and an inner `</table>` doesn't prematurely end an outer one. Only the *first* qualifying table is extracted; markup after it is ignored.
- **Rows in document order**: each `<tr>` produces one entry, and a row with no `<td>` cells yields an empty list (e.g. `<tr></tr>` → `[]`).
- **Cell text preserved exactly**: `convert_charrefs=True` (the default) means `handle_data` receives entity-decoded text (`&amp;` → `&`), and all inner tags (like `<b>`, `<br/>`, `<span>`) are simply skipped, so whitespace and inner text come through unchanged.
- **Malformed input tolerance**: unterminated `<tr>`/`<td>` tags are auto-closed when a following row/table tag (or end of input) appears, similar to how browsers recover.
- **No match / no rows**: returns `[]` if there's no such table or the table has no rows.

Example:

```python
>>> extract_data_table_rows(
...     "<table class='data-table'><tr><td>Header 1</td><td>Header 2</td></tr>"
...     "<tr><td>Data 1</td><td>Data 2</td></tr></table>")
[['Header 1', 'Header 2'], ['Data 1', 'Data 2']]

>>> extract_data_table_rows("<table class='other'><tr><td>x</td></tr></table>")
[]

>>> extract_data_table_rows('<table class="data-table"><tr><td>A &lt; B</td></tr><tr></tr></table>')
[['A < B'], []]
```

Here's a solution using only the standard library (no external dependencies), via a small tree-building wrapper around `html.parser`:

```python
from html.parser import HTMLParser

_VOID = {'br', 'img', 'input', 'hr', 'meta', 'link', 'area', 'base',
         'col', 'embed', 'param', 'source', 'track', 'wbr'}


class Element:
    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag
        self.attrs = {}
        for k, v in (attrs or []):
            self.attrs.setdefault(k, v if v is not None else '')
        self.parent = parent
        self.children = []          # mix of Element and str (text)


class TreeBuilder(HTMLParser):
    def __init__(self):
        # convert_charrefs=True decodes entities (&amp;, &#233;, ...) in text
        super().__init__(convert_charrefs=True)
        self.root = Element('[document]')
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        el = Element(tag, attrs, parent=self.stack[-1])
        self.stack[-1].children.append(el)
        if tag not in _VOID:
            self.stack.append(el)

    def handle_startendtag(self, tag, attrs):
        el = Element(tag, attrs, parent=self.stack[-1])
        self.stack[-1].children.append(el)

    def handle_endtag(self, tag):
        # pop back to the nearest matching open tag (tolerates sloppy HTML)
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return

    def handle_data(self, data):
        self.stack[-1].children.append(data)


def _classes(el):
    return (el.attrs.get('class') or '').split()


def _text(el):
    """Concatenated text of all descendants (nested tags removed)."""
    parts = []
    for child in el.children:
        if isinstance(child, str):
            parts.append(child)
        else:
            parts.append(_text(child))
    return ''.join(parts).strip()


def _descendants(el):
    for child in el.children:
        if isinstance(child, Element):
            yield child
            yield from _descendants(child)


def _first(el, tag, cls=None):
    """First descendant in document order with the given tag (and class)."""
    for d in _descendants(el):
        if d.tag == tag and (cls is None or cls in _classes(d)):
            return d
    return None


def extract_article_info(html):
    builder = TreeBuilder()
    builder.feed(html)
    builder.close()

    results = []
    for el in _descendants(builder.root):
        if el.tag == 'div' and 'container' in _classes(el):
            h1 = _first(el, 'h1')
            title = _text(h1) if h1 is not None else 'No Title'

            date_el = _first(el, 'span', 'date')
            date = _text(date_el) if date_el is not None else 'No Date'

            author_el = _first(el, 'span', 'author')
            author = _text(author_el) if author_el is not None else 'No Author'

            results.append((title, date, author))
    return results
```

How it works:

- **Tree building**: `TreeBuilder` accumulates the HTML into a lightweight tree of `Element` nodes and text strings. Text data passes through `convert_charrefs=True`, so entities like `&amp;` or `&#233;` are already decoded.
- **Class matching**: the `class` attribute is split on whitespace, so a div like `<div class="container article main">` still matches `"container"` (and matches even if "container" appears alongside other classes).
- **Text extraction**: `_text` recursively collects only text nodes, so nested tags are removed — e.g. `<h1>Hello <b>World</b></h1>` gives `"Hello World"` — and the result is stripped of surrounding whitespace.
- **Document order**: containers are found via a single pre-order traversal (`_descendants`), and the "first" `<h1>`/`<span>` inside each container likewise uses a document-order search.
- **Default values**: placeholders are used only when the *element* is entirely missing; an element that exists but is empty yields its stripped text (empty string).

Example checks:

```python
extract_article_info('<div class="container"><h1>Hello</h1>'
                     '<span class="author">Ann</span></div>')
# [('Hello', 'No Date', 'Ann')]

extract_article_info('<div class="container article">'
                     '<h1>A &amp; B</h1>'
                     '<span class="date">2024-01-01</span>'
                     '<span class="author extra">Bo</span></div>')
# [('A & B', '2024-01-01', 'Bo')]

extract_article_info('<div class="other"><h1>x</h1></div>')
# []  (not a container)
```

