def merge_and_standardize(rows1, rows2):
    """Outer-join two tables on 'id' and standardize the first table's
    feature columns to mean 0 and population std 1 (constant columns -> 0).
    Missing values are represented as None."""

    def feature_cols(rows):
        """Ordered list of non-'id' column names appearing in the rows."""
        cols = []
        for row in rows:
            for key in row:
                if key != 'id' and key not in cols:
                    cols.append(key)
        return cols

    cols1 = feature_cols(rows1)
    cols2 = feature_cols(rows2)

    # Compute mean and (population) std for each feature column of table 1,
    # ignoring missing (None) values.
    stats = {}
    for col in cols1:
        vals = [row[col] for row in rows1 if row.get(col) is not None]
        if vals:
            mean = sum(vals) / len(vals)
            var = sum((v - mean) ** 2 for v in vals) / len(vals)
            stats[col] = (mean, var ** 0.5)
        else:
            stats[col] = (0.0, 0.0)  # all values missing

    # Index rows by id (full outer join).
    by1 = {row['id']: row for row in rows1}
    by2 = {row['id']: row for row in rows2}

    merged = []
    for row_id in sorted(set(by1) | set(by2)):
        r1 = by1.get(row_id)
        r2 = by2.get(row_id)

        row = {'id': row_id}

        # Standardized features from table 1.
        for col in cols1:
            v = r1.get(col) if r1 else None
            if v is None:
                row[col] = None
            else:
                mean, std = stats[col]
                row[col] = 0.0 if std == 0 else (v - mean) / std

        # Raw features from table 2.
        for col in cols2:
            row[col] = r2.get(col) if (r2 and col in r2) else None

        merged.append(row)

    return merged
```

Example:

```python
rows1 = [{'id': 1, 'a': 1.0}, {'id': 2, 'a': 3.0}]
rows2 = [{'id': 2, 'b': 5.0}, {'id': 3, 'b': 7.0}]

print(merge_and_standardize(rows1, rows2))
# [{'id': 1, 'a': -1.0, 'b': None}, {'id': 2, 'a': 1.0, 'b': 5.0}, {'id': 3, 'a': None, 'b': 7.0}]
```

Key points:

- **Outer join:** union of ids from both tables, sorted ascending; missing rows/columns yield `None`.
- **Standardization:** computed with the *population* standard deviation (÷ n, not n−1), ignoring `None` values entirely (they don't affect mean/std and stay `None` in the output).
- **Constant columns:** std of 0 would cause division by zero, so those values become `0.0`.
- **Table 2 untouched:** its columns are passed through as-is.

