def normalize_columns(data_dict, data_keys):
    result = {}
    for key in data_keys:
        if key not in data_dict:
            continue
        col = data_dict[key]
        if not col:
            result[key] = []
            continue
        lo, hi = min(col), max(col)
        if hi == lo:
            result[key] = [0.0] * len(col)
        else:
            span = hi - lo
            result[key] = [(x - lo) / span for x in col]
    if not result:
        raise ValueError("None of the requested columns were found")
    return result
```

