print(normalize_columns({'A': [1, 2, 3], 'B': [4, 6, 5]}, ['B', 'X']))
# {'B': [0.0, 1.0, 0.5]}

print(normalize_columns({'A': [5, 5], 'B': [0, 10]}, ['A', 'B']))
# {'A': [0.0, 0.0], 'B': [0.0, 1.0]}
```

Key points:

- **Only present columns** are processed; missing names like `'X'` are silently ignored.
- **Constant columns** (min == max) scale to all zeros to avoid division by zero.
- **Order** of the returned dict follows the order of names in `data_keys`.
- If **no** requested names exist in `data_dict`, a `ValueError` is raised.

Here's a solution using Python's standard-library `HTMLParser`, which handles tag removal, entity decoding (via `convert_charrefs=True`), and whitespace stripping:

```python
from html.parser import HTMLParser


class _TableParser(HTMLParser):
    """Collects the header row and data rows of the table with a given id."""

    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)  # entities arrive already decoded
        self.table_id = table_id
        self.inside_target = False   # currently inside the target table?
        self.nested_depth = 0        # depth of tables nested inside the target
        self.saw_table = False       # did we ever see the target table?
        self.headers = None          # first row's cell texts
        self.rows = []               # each data row: list of cell texts
        self._row = None             # cells of the row being built
        self._cell = None            # text fragments of the cell being built

    # -- helpers ---------------------------------------------------------
    def _finalize_row(self):
        if self._row is not None and self._row:          # ignore cell-less rows
            if self.headers is None:
                self.headers = self._row                  # first row = header row
            else:
                self.rows.append(self._row)
        self._row = None
        self._cell = None

    def _collecting(self):
        # only collect while directly inside the target table (not nested ones)
        return self.inside_target and self.nested_depth == 0

    # -- tag handlers ------------------------------------------------------
    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            tid = dict(attrs).get('id')
            if not self.inside_target and not self.saw_table and tid == self.table_id:
                self.inside_target = True
                self.saw_table = True
            elif self.inside_target:
                self.nested_depth += 1
        elif not self._collecting():
            return
        if tag == 'tr':
            self._finalize_row()        # tolerate unclosed <tr>
            self._row = []
        elif tag in ('td', 'th'):
            if self._row is not None:
                self._cell = []

    def handle_endtag(self, tag):
        if tag == 'table':
            if self.inside_target:
                if self.nested_depth:
                    self.nested_depth -= 1
                else:
                    self.inside_target = False
                    self._finalize_row()
        elif not self._collecting():
            return
        if tag in ('td', 'th'):
            if self._cell is not None and self._row is not None:
                self._row.append(''.join(self._cell).strip())
                self._cell = None
        elif tag == 'tr':
            self._finalize_row()

    def handle_data(self, data):
        if self._cell is not None:
            self._cell.append(data)


def html_table_records(html, table_id):
    """Extract data records from the table with `table_id` in `html`.

    The table's first row is the header row; each later row becomes a dict
    mapping header text to cell text (tags removed, entities decoded,
    whitespace stripped). Raises ValueError if no such table exists.
    """
    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()

    if not parser.saw_table:
        raise ValueError(f"No table with id {table_id!r} found")
    if parser.headers is None:
        return []  # table existed but had no rows

    return [dict(zip(parser.headers, row)) for row in parser.rows]
```

**How it works:**

- **Table targeting:** The parser watches for `<table>` tags; when it finds one whose `id` matches (and it isn't already inside the target), it starts collecting. Nested tables inside the target are counted and ignored, so their rows don't pollute the output.
- **Header row:** The first `<tr>` encountered directly inside the table is treated as the header row, regardless of whether it uses `<th>` or `<td>`.
- **Cell extraction:** Cell text is accumulated from `handle_data` (with `convert_charrefs=True`, HTML entities like `&amp;` arrive already decoded), and each cell is `.strip()`ed when its closing tag arrives. Inner tags like `<b>` are simply skipped, so `<td><b> Alice </b></td>` yields `"Alice"`.
- **Robustness:** Unclosed `<tr>`/`<td>` tags are tolerated, malformed nesting is handled gracefully, and a missing id raises `ValueError`.

Example:

```python
html = ("<table id='t'>"
        "<tr><th>Name</th><th>Age</th></tr>"
        "<tr><td>Alice</td><td>25</td></tr>"
        "<tr><td>Bob</td><td>30</td></tr>"
        "</table>")
print(html_table_records(html, 't'))
# [{'Name': 'Alice', 'Age': '25'}, {'Name': 'Bob', 'Age': '30'}]
```

