import csv
import io


def concat_csv_tables(csv_texts):
    """Concatenate CSV documents (strings) that share the same columns.

    Each document must have a header row. All data rows from all
    documents are returned, in order, as a list of dicts mapping
    column name -> value. Columns whose values are all numeric are
    converted to int/float; other columns stay as strings.

    Raises ValueError if `csv_texts` is empty.
    """
    if not csv_texts:
        raise ValueError("csv_texts must contain at least one CSV document")

    def to_number(text):
        try:
            return int(text)
        except ValueError:
            try:
                return float(text)
            except ValueError:
                return None  # not numeric

    header = None
    data_rows = []

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text))
        rows = [row for row in reader if row]  # skip blank lines
        if not rows:
            continue
        doc_header = rows[0]
        if header is None:
            header = doc_header
        elif doc_header != header:
            raise ValueError("CSV documents do not share the same columns")
        data_rows.extend(rows[1:])

    if header is None or not data_rows:
        return []

    # Determine, per column, whether every value is numeric.
    numeric = [True] * len(header)
    for row in data_rows:
        for i, value in enumerate(row):
            if to_number(value) is None:
                numeric[i] = False

    result = []
    for row in data_rows:
        record = {}
        for i, name in enumerate(header):
            value = row[i]
            record[name] = to_number(value) if numeric[i] else value
        result.append(record)

    return result
```

Example usage:

```python
csv_texts = ["A,B\n0,3\n1,4\n", "A,B\n2,5\n"]
print(concat_csv_tables(csv_texts))
# [{'A': 0, 'B': 3}, {'A': 1, 'B': 4}, {'A': 2, 'B': 5}]

# Mixed types: A stays a string, B becomes a float
print(concat_csv_tables(["A,B\nfoo,1.5\nbar,2.5\n"]))
# [{'A': 'foo', 'B': 1.5}, {'A': 'bar', 'B': 2.5}]

concat_csv_tables([])  # raises ValueError
```

How it works:

- **Parsing:** each string is parsed with `csv.reader`, which correctly handles quoted fields. The first row of each document is the header (and is verified to match the others); the rest are data rows, collected in order.
- **Numeric detection:** a column is numeric only if *every* one of its values can be parsed as a number — first tried as an `int` (so `"3"` stays an integer), falling back to `float` (so `"3.5"` becomes a float). If any value fails, the column is left as strings.
- **Error handling:** an empty input list raises `ValueError`, and mismatched headers across documents also raise `ValueError`.

