import csv
import io


def sort_csv_rows(csv_text, sort_key):
    rows = list(csv.reader(io.StringIO(csv_text)))
    if not rows:
        return []
    header = rows[0]
    data = rows[1:]

    if sort_key not in header:
        raise ValueError(f"Column '{sort_key}' does not exist")

    col_index = {name: i for i, name in enumerate(header)}
    record_rows = [dict(zip(header, row)) for row in data]

    def to_number(value):
        try:
            return int(value)
        except ValueError:
            return float(value)

    def is_numeric(column_name):
        idx = col_index[column_name]
        values = [row[idx] for row in data if row[idx] != '']
        if not values:
            return False
        for value in values:
            try:
                to_number(value)
            except ValueError:
                return False
        return True

    # Convert numeric columns to numbers
    for name in header:
        if is_numeric(name):
            idx = col_index[name]
            for row in record_rows:
                if row[name] != '':
                    row[name] = to_number(row[name])

    # Python's sort is stable, so rows with equal keys keep original order
    return sorted(record_rows, key=lambda row: row[sort_key])
```

Example:

```python
result = sort_csv_rows('title,x\nBook C,10\nBook A,9\nBook B,100\n', 'x')
# [{'title': 'Book A', 'x': 9}, {'title': 'Book C', 'x': 10}, {'title': 'Book B', 'x': 100}]
```

Key implementation points:

- **Numeric detection**: A column is treated as numeric only if every non-empty value in that column parses as an `int` or `float`. Ints are preferred when possible so they display cleanly.
- **Stable sort**: `sorted` in Python is stable, so rows with equal sort keys automatically preserve their original relative order.
- **Error handling**: A `ValueError` is raised if `sort_key` isn't among the header columns.
- **Quoting/escaping**: Using the `csv` module means quoted fields with embedded commas are handled correctly.

