import csv
import io


def _cbrt(x):
    if x < 0:
        return -((-x) ** (1.0 / 3.0))
    return x ** (1.0 / 3.0)


def csv_cube_roots(csv_text, columns):
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        return ({}, {})

    header = rows[0]
    data = {name: [] for name in header}

    for row in rows[1:]:
        if not row:
            continue
        for name, value in zip(header, row):
            try:
                data[name].append(float(value))
            except ValueError:
                raise ValueError(f"Non-numeric value {value!r} in column {name!r}")

    cube_roots = {}
    for name in columns:
        if name not in data:
            raise KeyError(f"Column {name!r} not found in file")
        cube_roots[name] = [_cbrt(v) for v in data[name]]

    return (data, cube_roots)
