import re

_WHITESPACE = b' \t\r\n\x0b\x0c'


def _is_ws(byte):
    return bytes([byte]) in (b' ', b'\t', b'\r', b'\n', b'\x0b', b'\x0c')


def _next_token(data, pos):
    """Read the next header token starting at `pos`, skipping whitespace
    and '#'-comments. Returns (token, new_pos) or (None, pos) at end."""
    n = len(data)
    # Skip leading whitespace and comments
    while pos < n:
        if _is_ws(data[pos]):
            pos += 1
        elif data[pos:pos + 1] == b'#':
            while pos < n and not _is_ws(data[pos]):
                pos += 1
        else:
            break
    if pos >= n:
        return None, pos
    start = pos
    while pos < n and not _is_ws(data[pos]) and data[pos:pos + 1] != b'#':
        pos += 1
    return data[start:pos], pos


def _parse_int(token):
    try:
        return int(token)
    except (ValueError, TypeError):
        raise ValueError("invalid integer in header: %r" % (token,))


def grayscale_histogram(data):
    data = bytes(data)

    # --- Parse magic number ---
    pos = 0
    magic, pos = _next_token(data, pos)
    if magic not in (b'P5', b'P2'):
        raise ValueError("not a PGM file (bad magic number)")

    # --- Parse width, height, maxval ---
    fields = []
    for _ in range(3):
        token, pos = _next_token(data, pos)
        if token is None:
            raise ValueError("incomplete PGM header")
        fields.append(_parse_int(token))
    width, height, maxval = fields

    if width <= 0 or height <= 0:
        raise ValueError("invalid dimensions: %d x %d" % (width, height))
    if not (1 <= maxval <= 255):
        raise ValueError("only 8-bit PGM images (1 <= maxval <= 255) are supported")

    histogram = {}

    if magic == b'P5':
        # Binary variant: exactly one whitespace character separates the
        # maxval from the raster data.
        if pos >= len(data) or not _is_ws(data[pos]):
            raise ValueError("missing whitespace after maxval")
        pos += 1
        raster = data[pos:]
        if len(raster) != width * height:
            raise ValueError(
                "expected %d bytes of pixel data, got %d"
                % (width * height, len(raster))
            )
        for value in raster:
            if value > maxval:
                raise ValueError("pixel value %d exceeds maxval %d" % (value, maxval))
            histogram[value] = histogram.get(value, 0) + 1
    else:
        # ASCII variant: whitespace-separated decimal pixel values.
        values = []
        while True:
            token, pos = _next_token(data, pos)
            if token is None:
                break
            value = _parse_int(token)
            if not (0 <= value <= maxval):
                raise ValueError(
                    "pixel value %d out of range 0..%d" % (value, maxval)
                )
            values.append(value)
        if len(values) != width * height:
            raise ValueError(
                "expected %d pixel values, got %d" % (width * height, len(values))
            )
        for value in values:
            histogram[value] = histogram.get(value, 0) + 1

    return histogram
```

**Notes on the implementation:**

- **Header parsing** handles arbitrary whitespace and `#`-comments (which run to the end of the line), as allowed by the PGM spec.
- **Validation:** it raises `ValueError` for a bad magic number, non-integer/negative dimensions, `maxval` outside 1–255 (only 8-bit images are supported), pixel values exceeding `maxval`, and a pixel count that doesn't match `width × height` (too few or too many, in both the P5 and P2 variants).
- **P5 specifics:** per the spec, exactly one whitespace byte separates `maxval` from the raster data, so the parser consumes a single whitespace character and requires the remaining byte count to equal `width * height`.
- Only pixel values that actually occur appear as keys in the returned dict.

Example:

```python
>>> grayscale_histogram(b'P5\n2 2\n255\n\x00\x01\x02\xff')
{0: 1, 1: 1, 2: 1, 255: 1}
>>> grayscale_histogram(b'P2\n2 2\n255\n0 1\n2 255')
{0: 1, 1: 1, 2: 1, 255: 1}
```
